#!/usr/bin/env python3
import json
from pathlib import Path
BASE = Path(__file__).resolve().parent
d = json.loads((BASE / 'matrix.json').read_text())
s = d['summary']
lines = ['# Animation family coverage and single-sprite authoring contract', '', 'This covers the animation kinds actually found in this **player-focused extraction and captured native effect routes**. It is not an inventory of every enemy, boss, NPC gesture, chest, terrain or background animation in the game. Unknown generic action rows remain unknown.', '', f"The evidence contains {s['normal_decoded_bindings']:,} normal nominal bindings / {s['normal_exported_body_frames']:,} body frames; {s['transformed_nominal_bindings']:,} transformed nominal bindings; and {s['native_public_routes']} captured native routes / {s['native_public_frames']:,} presented video ticks. **None of these counts is new authored artwork.** The new layered pilot has only {s['authored_pilot_clips']} clips (walk and punch), {s['authored_pilot_frames']} frames and {s['authored_pilot_layers']} layers; **zero clips have production art approval**. Both request visual refinement.", '', f"Current input fingerprint: `{d['input_fingerprint']}`. `matrix.json` holds the exact source-file/route hashes, sampled private capture references, recipes and QC requirements. Its {len(d['source_audit']['checks'])} fresh checks audit count/hash/clock consistency; historical all-pixel/Godot reports remain separate proofs, not a claim this audit rendered every pixel again.", '', '## Bound evidence stages', '', '| Stage | What it establishes | What it does not establish |', '|---|---|---|', '| Decoded binding | Table/script/body/palette mapping and a nominal default-status path | Every allocated row is reachable, every wait has finite duration, or FF is a fixed native loop |', '| Runtime observed | Exact native input/context/state and presented capture window | All actors, directions, levels, targets, interruption or cleanup branches |', '| Exported/tested | Specific pixels, hashes, clocks, resource imports or actual tool exchange pass | Authored content or artistic quality |', '| Newly authored | Explicit new editable character/effect frame assets exist | Native equivalence or finished art |', '| Quality approved | Current hash-bound review approves the specified authored clips | Another revision or missing views |', '| Engine behavior | Named parser, shader, palette, playback or state-component checks | A complete reconstructed RPG/combat system |', '', '## Source-grounded families and how to build them from one sprite', '', 'One fused sprite can supply identity, visible material colors and one view. It cannot prove hidden joints, back/other views or replacement transformed characters. Build declared layers/anchors, draw additional key poses when the source is insufficient, preserve one render/ground frame, and use distinct effect instances/palette state rather than pretending every type is one body GIF.', '']
for f in d['families']:
    lines += ['### ' + f['label'], '', '**Identity:** `' + f['id'] + '`; ' + f['label_status'] + '.', '', '**Source coverage:** decoded ' + json.dumps(f['decoded_bindings']) + '; observed ' + json.dumps(f['runtime_observed']) + '; exported ' + json.dumps(f['exported_tested']) + '.', '', '**Authoring:** ' + ' '.join(f['single_sprite_authoring_recipe']), '', '**QC:** ' + ' '.join(f['actual_QC_checks_required']), '', '**Engine scope:** ' + f['engine_behavior'], '', '**Still missing:** ' + ' '.join(f['remaining_gaps']), '']
lines += ['## All42 captured normal spell IDs', '', 'These are native spell labels from the current hashed route index, not42 newly painted effects. Original all-living Revivify was rejected; the actual dead-target route supplies successful ID21(hex). Cast/effect/target and palette behavior remain separate components.', '', '| ID hex | Caster | Source spell label | Actual indexed route |', '|---|---|---|---|']
for r in d['spells']:
    lines.append('| ' + r['hex_id'] + ' | ' + r['caster'] + ' | ' + r['source_label'] + ' | `' + r['route_id'] + '` |')
lines += ['', '## Native method and causal learning boundary', '', '`matrix.json` links native parser/frame-fetch/body assembly and projectile instance contracts separately from authored assets. Per-type semantic-method and causal-proof fields remain null where unproven. Bounded 65816 width assumptions remain explicit; CPU watchpoint co-occurrence is not a causal callgraph. The parent-owned one-byte normal right Sword experiment now has at least 273 passing checks (313 in the current receipt): control byte 1C→19 changes the first displayed hold from 5 to 10 native ticks, retains subsequent holds of 5/5, and delays later poses/completion by 5 ticks. Independent scalar OAM/VRAM/CGRAM reconstruction supports one-tick presentation lag and rejects zero/two-tick lag. This establishes only that bounded original-game intervention, not a method mapping for other types or newly authored art.', '', 'The corrected-player GPU bridge adds **255 actual first/middle/last rendered samples across 85 unchanged routes**, compared with independently raw-rebuilt hardware goldens (11,832 scalar checks). The old full 28,123-frame GPU proof remains bound to its old player; no restamp or full corrected-player render is claimed. The separate current engine clock receipt has 9,881 checks on 14 routes. Historical four-binding stale gate receipts remain in `historical-stale/`; current browser QA is rehashed independently.', '', '## Completeness gates and reproduction', '', 'The production target contract proposes four views for ordinary hero/equipment/casting assets and context-gated bindings for transformed/status/lifecycle families. It does not assert that every native source script is reachable in every view. The contract is separately frozen in `requirements.json`; changing it changes the requested scope and requires review.', '', f"`new_art_complete` intentionally fails all **{len(d['requirements'])} minimum required binding atoms**, plus unresolved semantic/context scope gaps. These 639 minimum targets are not a complete whole-game specification. A pilot walk/punch is not aliased to Randi, Primm, Popoi, a sword attack,42 spells or transformed configurations. Accounting known families is a separate gate from finished-art completeness.", '', '```sh', 'python3 qc/coverage/build_matrix.py', 'python3 qc/coverage/validate.py qc/coverage/matrix.json --requirements qc/coverage/requirements.json --gate discovered_family_accounting --verify-sources --report qc/coverage/accounting-gate.json', 'python3 qc/coverage/validate.py qc/coverage/matrix.json --requirements qc/coverage/requirements.json --gate decoded_idle_walk_exact_views --report qc/coverage/decoded-gate.json', '# Expected failure until exact new assets and current approvals exist:', 'python3 qc/coverage/validate.py qc/coverage/matrix.json --requirements qc/coverage/requirements.json --gate new_art_complete --report qc/coverage/production-gap-gate.json', 'python3 qc/coverage/test_validate.py', '```', '', 'Negative tests remove a complete returning-weapon family, remove the left walk, try a right-view alias, duplicate identities, change equipment/actor, fabricate approval states and alter a source hash. They must fail the **specific missing/stale/unsupported** condition; no fallback silently fills the requirement.', '', '## Current audit findings', '']
failed = [c['name'] for c in d['source_audit']['checks'] if not c['passed']]
lines += ['- ' + n for n in failed] if failed else ['All fresh source count/hash/timing crosschecks pass.']
lines += ['', 'Pixel presentation is authoritative:815 transformed current-WRAM poses were exactly one video tick ahead of hardware, and two config-copy transitions preceded body assembly. Normal static ordinary-weapon exports use a baseline palette; independent native palette state is not baked into them. Public OBJ replay excludes backgrounds, color math, scanline overflow and priority rotation. Native hash bindings and browser tests do not constitute deployment verification.', '', 'Actionable next work: author and independently review exact requested views/actions/effect assets; add missing run and charge directions/actors, missing charge-level contexts, semantic event/gesture identification, complete conditional dispatcher contracts and relevant spell target/level/cleanup branches. Additional rows or counts cannot close those gaps.']
lines += ['', 'The approval stage additionally requires actual authored project/export evidence and a current approval artifact. A project must declare provenance.asset_role=authored_new_art; the review file must contain decision=approved, exact requested clip_ids, input_fingerprint and asset_sha256 keyed by the matrix evidence IDs. The validator reads the real review file and current asset bindings, so relabelling a changes_requested receipt in a coverage row cannot pass. This verifies approval evidence consistency, not artistic judgment.']
(BASE / 'README.md').write_text('\n'.join(lines) + '\n')
